<script>$('.product-thumb').on('click',function(){$('#main-product-image').attr('src',$(this).data('src'))});$('#qty-minus').on('click',function(){$('#qty').val(Math.max(1,Number($('#qty').val())-1))});$('#qty-plus').on('click',function(){$('#qty').val(Math.min({{ $details->stock }},Number($('#qty').val())+1))});$('input[name="product_size"]').on('change',function(){$('#selected-size').text(': '+$(this).val())});(function(){const item=@json($analyticsItem);window.dataLayer=window.dataLayer||[];dataLayer.push({ecommerce:null});dataLayer.push({event:'view_item',ecommerce:{currency:'BDT',value:item.price,items:[item]}});if(typeof fbq==='function')fbq('track','ViewContent',{content_ids:[item.item_id],content_type:'product',value:item.price,currency:'BDT'});$('#product-order-form').on('submit',function(){const tracked=Object.assign({},item,{quantity:Number($('#qty').val())});dataLayer.push({ecommerce:null});dataLayer.push({event:'add_to_cart',ecommerce:{currency:'BDT',value:tracked.price*tracked.quantity,items:[tracked]}});if(typeof fbq==='function')fbq('track','AddToCart',{content_ids:[item.item_id],content_type:'product',value:tracked.price*tracked.quantity,currency:'BDT'})})})();</script>
